package com.toji.settings;

import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.provider.Settings;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import rikka.shizuku.Shizuku;

public class MainActivity extends Activity {
    final int BG=0xff100d18, PANEL=0xff211b2c, PURPLE=0xffa444f4, LIGHT=0xffc782ff, MUTED=0xffaaa4b4, WHITE=0xfff7f3fa;
    final String[] tabs={"Início","Booster","Sensi","Perfil"}, symbols={"⌂","ϟ","☷","♙"};
    final String[] labels={"Geral","Mira Red Dot","Mira 2x","Mira 4x","Sniper","Câmera"};
    final int[] defaults={100,90,85,75,55,78};
    LinearLayout page,content,bar; android.content.SharedPreferences prefs; String current="Início";
    private final Shizuku.OnBinderReceivedListener received = () -> runOnUiThread(() -> { if ("Booster".equals(current)) show("Booster"); });
    private final Shizuku.OnBinderDeadListener died = () -> runOnUiThread(() -> { if ("Booster".equals(current)) show("Booster"); });
    private final Shizuku.OnRequestPermissionResultListener permissionResult = (requestCode, grantResult) -> runOnUiThread(() -> {
        if (requestCode == 1001) { show("Booster"); info(grantResult == PackageManager.PERMISSION_GRANTED ? "Shizuku autorizado." : "Autorização negada."); }
    });
    @Override public void onCreate(Bundle b) { super.onCreate(b); getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(Color.BLACK); prefs=getSharedPreferences("toji_v2",MODE_PRIVATE); Shizuku.addBinderReceivedListenerSticky(received); Shizuku.addBinderDeadListener(died); Shizuku.addRequestPermissionResultListener(permissionResult);show("Início"); }
    @Override protected void onDestroy() { Shizuku.removeBinderReceivedListener(received); Shizuku.removeBinderDeadListener(died); Shizuku.removeRequestPermissionResultListener(permissionResult);super.onDestroy(); }
    int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    GradientDrawable shape(int color,int r){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(r));return d;}
    TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
    LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    void add(LinearLayout parent,View v,int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(top);parent.addView(v,p);}
    void pad(View v,int x,int y){v.setPadding(dp(x),dp(y),dp(x),dp(y));}
    LinearLayout card(String title,String subtitle){LinearLayout c=col();pad(c,18,19);c.setBackground(shape(PANEL,20));add(content,c,15);if(title!=null)add(c,text(title,18,WHITE,true),0);if(subtitle!=null)add(c,text(subtitle,13,MUTED,false),9);return c;}
    void btn(LinearLayout p,String name,Runnable action){TextView t=text(name,14,WHITE,true);t.setGravity(Gravity.CENTER);pad(t,12,16);t.setBackground(shape(PURPLE,15));add(p,t,14);t.setOnClickListener(v->action.run());}
    void info(String message){if(!isFinishing())new AlertDialog.Builder(this).setMessage(message).setPositiveButton("OK",null).show();}
    void heading(String title,String subtitle){add(content,text(title,27,WHITE,true),24);if(subtitle!=null)add(content,text(subtitle,14,MUTED,false),12);}
    void show(String tab){current=tab;page=col();page.setBackgroundColor(BG);setContentView(page);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=col();pad(content,19,12);scroll.addView(content);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(tab.equals("Início"))home();else if(tab.equals("Booster"))booster();else if(tab.equals("Sensi"))sensi();else profile();bar=new LinearLayout(this);bar.setBackgroundColor(PANEL);bar.setPadding(dp(8),dp(9),dp(8),dp(8));page.addView(bar);for(int i=0;i<tabs.length;i++){final String target=tabs[i];LinearLayout item=col();item.setGravity(Gravity.CENTER);boolean selected=tab.equals(target);TextView icon=text(symbols[i],27,selected?WHITE:MUTED,true);icon.setGravity(Gravity.CENTER);if(selected){icon.setBackground(shape(0xff8743c3,20));icon.setPadding(dp(18),0,dp(18),0);}item.addView(icon,new LinearLayout.LayoutParams(-2,dp(36)));TextView name=text(tabs[i],12,selected?WHITE:MUTED,selected);name.setGravity(Gravity.CENTER);add(item,name,5);bar.addView(item,new LinearLayout.LayoutParams(0,dp(64),1));item.setOnClickListener(v->show(target));}}

    void brand(){TextView logo=text("TOJI SETTINGS",27,PURPLE,true);logo.setGravity(Gravity.CENTER);add(content,logo,24);TextView sub=text("BLOOD STRIKE  |  GAME BOOSTER",11,MUTED,false);sub.setGravity(Gravity.CENTER);add(content,sub,6);}
    void home(){brand();add(content,text("Bem-vindo, "+prefs.getString("nickname","Jogador"),23,WHITE,true),36);LinearLayout a=card("⚡ Game Booster","Prepare seu dispositivo e verifique o Shizuku.");btn(a,"ABRIR GAME BOOSTER",()->show("Booster"));LinearLayout g=card("🎮 Jogos","Abra um jogo instalado no celular.");btn(g,"ABRIR BLOOD STRIKE",()->openGame("com.netease.newspike"));btn(g,"ABRIR FREE FIRE",()->openGame("com.dts.freefireth","com.dts.freefiremax"));LinearLayout s=card("🎯 Sensibilidade","Configure perfis e salve seus valores.");btn(s,"AJUSTAR SENSIBILIDADE",()->show("Sensi"));card("✦ Toji Settings V3","Tema escuro • Ferramentas locais • Perfis salvos");}
    void openGame(String... pkgs){PackageManager pm=getPackageManager();for(String p:pkgs){Intent launch=pm.getLaunchIntentForPackage(p);if(launch!=null){startActivity(launch);return;}}info("Jogo não encontrado.");}
    void requestShizuku(){ResolutionController.Result state=ResolutionController.status();if(state.ok){info("Shizuku já autorizado.");return;}try{if(!Shizuku.pingBinder()){Intent i=getPackageManager().getLaunchIntentForPackage("moe.shizuku.privileged.api");if(i!=null)startActivity(i);else info("Abra o Shizuku e inicie o serviço.");return;}Shizuku.requestPermission(1001);}catch(Throwable t){info("Erro ao solicitar autorização: "+t.getMessage());}}
    void booster(){heading("Game Booster","Status do Shizuku e ferramentas do dispositivo.");ResolutionController.Result state=ResolutionController.status();boolean running=false;try{running=Shizuku.pingBinder();}catch(Throwable ignored){}LinearLayout c=card("♢  "+(state.ok?"SHIZUKU CONECTADO":running?"SHIZUKU SEM PERMISSÃO / ERRO":"SHIZUKU DESLIGADO"),state.message);btn(c,"CONECTAR / AUTORIZAR",this::requestShizuku);btn(c,"⟳ ATUALIZAR STATUS",()->show("Booster"));btn(c,"TESTAR COMANDO (SEM ALTERAR TELA)",()->new Thread(()->{ResolutionController.Result r=ResolutionController.testConnection();runOnUiThread(()->info((r.ok?"✓ ":"✕ ")+r.message));}).start());card("ⓘ Como conectar","1. Inicie o Shizuku.\n2. Autorize o Toji Settings.\n3. Toque em testar comando.\n4. Só depois aplique a resolução.");card("▣ APPS EM EXECUÇÃO","O Android limita a visualização de outros processos.");card("◈ SEU DISPOSITIVO",Build.MANUFACTURER+" "+Build.MODEL+" • Android "+Build.VERSION.RELEASE);LinearLayout manage=card("♧ GERENCIAR SEGUNDO PLANO","Use as configurações do Android para controlar apps.");btn(manage,"ABRIR GERENCIAMENTO DE APPS",()->startActivity(new Intent("android.settings.APPLICATION_SETTINGS")));stretch();}
    void stretch(){LinearLayout c=card("▣ TELA ESTICADA • BLOOD STRIKE","A resolução altera a tela inteira do Android.");btn(c,"ABRIR PAINEL FLUTUANTE",()->{if(!Settings.canDrawOverlays(this)){startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));return;}try{startService(new Intent(this,FloatingPanelService.class));info("Painel flutuante iniciado!");}catch(Exception e){info("Erro no painel: "+e.getMessage());}});btn(c,"RESTAURAR RESOLUÇÃO",()->new Thread(()->{ResolutionController.Result r=ResolutionController.restore(this);runOnUiThread(()->info(r.message));}).start());}
    void sensi(){heading("Sensibilidade","Crie seu perfil e ajuste valores de referência.");LinearLayout p=card("🎯 PERFIS DE MIRA","Perfil atual: "+prefs.getString("profile","Equilibrado"));btn(p,"⚡ RUSH",()->preset("Rush",new int[]{120,110,100,90,65,100}));btn(p,"◎ EQUILIBRADO",()->preset("Equilibrado",defaults));btn(p,"⊕ PRECISÃO",()->preset("Precisão",new int[]{80,75,70,60,40,65}));for(int i=0;i<labels.length;i++){final int index=i;LinearLayout c=card(labels[i],null);int val=prefs.getInt("v"+i,defaults[i]);TextView number=text("Valor: "+val,14,LIGHT,false);add(c,number,10);SeekBar seek=new SeekBar(this);seek.setMax(200);seek.setProgress(val);add(c,seek,5);seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int v,boolean from){number.setText("Valor: "+v);if(from)prefs.edit().putInt("v"+index,v).putString("profile","Personalizado").apply();}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});}btn(content,"SALVAR CONFIGURAÇÕES",()->info("Valores salvos neste celular. Aplique manualmente no jogo."));add(content,text("Os ajustes não modificam arquivos dos jogos.",12,MUTED,false),15);}
    void preset(String name,int[] values){android.content.SharedPreferences.Editor e=prefs.edit().putString("profile",name);for(int i=0;i<values.length;i++)e.putInt("v"+i,values[i]);e.apply();show("Sensi");}
    void profile(){heading("Meu Perfil",null);LinearLayout c=card("👤 Jogador","Perfil salvo neste dispositivo.");EditText input=new EditText(this);input.setSingleLine(true);input.setTextColor(WHITE);input.setHintTextColor(MUTED);input.setText(prefs.getString("nickname","Jogador"));input.setHint("Apelido");input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);add(c,input,15);btn(c,"SALVAR APELIDO",()->{String n=input.getText().toString().trim();if(n.isEmpty()){info("Digite um apelido.");return;}prefs.edit().putString("nickname",n).apply();info("Apelido salvo!");});LinearLayout s=card("⚙ Configurações","Versão 3.1 • Shizuku e Stretch");btn(s,"RESTAURAR SENSIBILIDADE",()->new AlertDialog.Builder(this).setTitle("Restaurar sensibilidade?").setNegativeButton("CANCELAR",null).setPositiveButton("RESTAURAR",(d,w)->{android.content.SharedPreferences.Editor e=prefs.edit().putString("profile","Equilibrado");for(int i=0;i<defaults.length;i++)e.putInt("v"+i,defaults[i]);e.apply();info("Sensibilidade restaurada.");}).show());card("ⓘ Sobre","Toji Settings V3. Os perfis são referências locais e o Stretch altera a resolução global do Android.");}
}
